_If_ you want to you could make this code safer by creating a RAII type for this lock.
Something like this:
```cpp
struct MidiAudioLock;

class MidiAudio
{
public:
    MidiAudioLock Lock()
    {
        _inUseMutex.lock();
        return { *this };
    }

private:
    friend struct MidiAudioLock;
    void Unlock() { /*...*/ }
};

struct MidiAudioLock {
    explicit constexpr MidiAudioLock(MidiAudio& midi) noexcept : _midi{ midi } {}

    MidiAudioLock(MidiAudioLock&&) = default;
    MidiAudioLock& operator=(MidiAudioLock&&) = default;
    MidiAudioLock(const MidiAudioLock&) = delete;
    MidiAudioLock& operator=(const MidiAudioLock&) = delete;

    ~MidiAudioLock()
    {
        _midi.Unlock();
    }

private:
    MidiAudio& _midi;
};
```

Oh, I thought it'd be fine to just do this:
```cpp
void MidiAudio::PlayNote(const int noteNumber, const int velocity, const std::chrono::microseconds duration)
{
    if (_shutdown)
    {
        return;
    }

    // ...
}
```

It would still process the VT sequence, but effectively stop doing anything with it.
I thought that this would be equivalent to using an exception. After all, we don't have a `ShutdownException` for other sequences either. 🤔
